import{_ as o,C as t,o as n,c as l,E as a,a2 as s}from"./chunks/framework.Cc8dJFaW.js";const b=JSON.parse('{"title":"地址看起来相同，签发者身份就相同吗？","description":"","frontmatter":{"title":"地址看起来相同，签发者身份就相同吗？","article_type":"experiment-report","edition":"research-center","research_question":"签发者辅助函数是否合并了严格字符串比较所区分的地址？","summary":"三组有效地址在签发者辅助函数下相等，在严格字符串比较下不等。隔离探针揭示比较合同的差异，并为真实回调路径留下明确的待验证问题。","sources":"https://github.com/google-gemini/gemini-cli/pull/30454, https://modelcontextprotocol.io/specification/latest/basic/authorization","date":"2026-11-28","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261128-002","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-28-sig-20261128-002-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-28-sig-20261128-002.md","filePath":"zh/engineering/2026-11-28-sig-20261128-002.md","lastUpdated":null}'),c={name:"zh/engineering/2026-11-28-sig-20261128-002.md"};function d(p,e,h,g,m,u){const r=t("ArticleCover"),i=t("ArticleTableScroll");return n(),l("div",null,[a(r,{image:"/assets/covers/daily-2026-11-28-sig-20261128-002-cover.png",kicker:"研究成果",title:"地址看起来相同，签发者身份就相同吗？",summary:"三组有效地址在签发者辅助函数下相等，在严格字符串比较下不等。隔离探针揭示比较合同的差异，并为真实回调路径留下明确的待验证问题。",version:"2026-11-28",languageHref:"/en/engineering/2026-11-28-sig-20261128-002",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=s('<h1 id="地址看起来相同-签发者身份就相同吗" tabindex="-1">地址看起来相同，签发者身份就相同吗？ <a class="header-anchor" href="#地址看起来相同-签发者身份就相同吗" aria-label="Permalink to &quot;地址看起来相同，签发者身份就相同吗？&quot;">​</a></h1><p>两个签发者地址只差一个尾斜杠，辅助函数判为相等，严格字符串比较却判为不等。本次隔离实验确实观察到这个差异；它尚不是一次真实登录绕过。对授权客户端实现者而言，关键是先确定正在比较“可规范化的地址”还是“协议要求原样匹配的身份”，再把测试接到实际回调入口。</p><h2 id="三组有效输入-两个相等关系" tabindex="-1">三组有效输入，两个相等关系 <a class="header-anchor" href="#三组有效输入-两个相等关系" aria-label="Permalink to &quot;三组有效输入，两个相等关系&quot;">​</a></h2><p>OAuth（开放授权协议）客户端会使用签发者标识区分授权来源。MCP（模型上下文协议）已读授权规范快照标注为 2026-07-28，其中的回调响应校验要求，在比较已解码的签发者字符串前，不得进行方案或主机大小写折叠、默认端口消除、尾斜杠或百分号编码规范化。<a href="https://modelcontextprotocol.io/specification/latest/basic/authorization" target="_blank" rel="noreferrer">授权规范：回调响应校验</a></p><p>而 Gemini CLI（谷歌双子命令行客户端）第 30454 号合并请求的已读头版本中，共享签发者比较函数会规范化来源并裁去路径尾斜杠。分析阶段的内部实验，从该差异文件提取原函数，发现以下有效安全超文本地址对在辅助函数下相等，在严格比较下不等。</p><table tabindex="0"><thead><tr><th>地址对的差别</th><th>辅助函数</th><th>已解码字符串严格比较</th></tr></thead><tbody><tr><td>主机名的大写与小写</td><td>相等</td><td>不等</td></tr><tr><td>显式默认端口与省略默认端口</td><td>相等</td><td>不等</td></tr><tr><td>路径末尾有斜杠与无斜杠</td><td>相等</td><td>不等</td></tr></tbody></table><p>这里每个结果都是内部函数探针的观察，不是第三方安全验证。具体输入、全部 11 个输出及对照条件见<a href="/joinwell52/assets/evidence/2026-11-28-sig-20261128-002/experiment-evidence.json">内部隔离实验记录</a>。表格把差异限定在相等关系，没有把同源、可信签发者或安全登录混为一谈。</p><h2 id="提取函数执行到哪里为止" tabindex="-1">提取函数执行到哪里为止 <a class="header-anchor" href="#提取函数执行到哪里为止" aria-label="Permalink to &quot;提取函数执行到哪里为止&quot;">​</a></h2><p>实验绑定的合并请求头提交为 c7e8d01912b897f6e1dc7c2a2765831f72b231e0。提取来自已读差异文件的两个原函数，转换只去除导出关键字与类型标注，保留函数体；在分析阶段的本机 JavaScript（脚本语言）环境中执行，使用标准地址解析器，没有网络授权或模拟远端服务。<a href="https://github.com/google-gemini/gemini-cli/blob/c7e8d01912b897f6e1dc7c2a2765831f72b231e0/packages%2Fcore%2Fsrc%2Fmcp%2Foauth-utils.ts" target="_blank" rel="noreferrer">固定版本的辅助函数来源</a></p><p>11 个用例中，完全相同的有效地址是正对照；租户路径、查询、片段、用户信息与编码差异提供边界探针。所测用户信息输入被拒绝；路径、查询、片段与百分号编码差异没有被合并为同一身份。不能把某些规范化差异概括成所有字符串都被宽松接受。</p><p>另有两项故意使用非法地址的探针：相同的非地址字符串被判相等，两个相差尾斜杠的相对字符串也可能相等。这说明单独的比较辅助函数不是完整地址验证器，却不说明这些字符串能抵达生产回调。前置校验可能已把它们排除。严格字符串比较本身同样不是一个完整协议验证器。</p><h2 id="地址校验与身份比较不能代班" tabindex="-1">地址校验与身份比较不能代班 <a class="header-anchor" href="#地址校验与身份比较不能代班" aria-label="Permalink to &quot;地址校验与身份比较不能代班&quot;">​</a></h2><p>已读补丁还涉及发现后重新检查端点、显示授权与令牌来源的用户同意，以及刷新端点绑定。手动跨来源例外要求不使用发现，并预先显式提供所需授权地址、令牌地址和客户端标识。这些是补丁中的不同分支；检查了测试文本，不等于实际执行了完整同意流程。<a href="https://github.com/google-gemini/gemini-cli/pull/30454" target="_blank" rel="noreferrer">合并请求与差异</a></p><p>它们回答“凭据将发往哪里”，而回调签发者比较回答“返回的身份是否符合预期”。资源令牌的受众绑定又回答“令牌是否发给这个资源服务”。规范允许资源服务与授权服务分离，不能把补丁中的端点来源约束误写成两类服务必须同源。</p><p>本研究的解释是：复用一个地址处理函数前，应先核对调用点的相等合同。用于发现元数据的规范化可能有意如此；回调身份匹配却可能要求保留字符串差异。规范与补丁分别由不同主体维护，它们支持比较的两侧，没有对补丁的安全效果作相互独立复现。</p><h2 id="下一项证据必须来自真实回调" tabindex="-1">下一项证据必须来自真实回调 <a class="header-anchor" href="#下一项证据必须来自真实回调" aria-label="Permalink to &quot;下一项证据必须来自真实回调&quot;">​</a></h2><p>需要取得固定版本的完整回调源码和前置校验，再从已解码的签发者参数进入真实调用路径，分别测试这三组有效地址差异。还应检查错误响应是否同样受身份失配约束，且不把响应显示或行动发生误当成比较函数的输出。这些是后续研究请求，本次没有执行。</p><p>如果实际路径调用别的严格比较函数，或者前置校验拒绝某些形式，当前辅助函数结果就不能直接外推；如果实际路径确实使用该规范化函数，还需记录实际到达的分支及后果，才能讨论符合性或安全影响。两种解释都需要调用路径证据。</p><p>因此，本次成立的结论是：三组有效地址暴露了辅助函数与已读回调规范的比较合同差异。未执行完整仓库测试、授权网络请求、回调服务、动态客户端注册、令牌刷新或利用。该辅助函数原已存在于回调代码中，此补丁把它移到共享位置，不能据此声称新补丁引入了这些相等关系或一个新漏洞。</p><p>证据与引用的边界：合并请求代码与测试属于同一工程主体；规范是另一主体的规范性来源；11 个用例是内部实验依据。固定版本和规范快照均取自 2026-11-28 已完成研究，没有以当前远端分支替换输入。引用、发表或合并状态不等于独立验证。本次不生成社区版，避免在真实回调后果尚未建立时把局部差异包装成漏洞讨论。</p>',20))])}const f=o(c,[["render",d]]);export{b as __pageData,f as default};
